const MAP = {
 0x1b:"Y",0x1c:"Y",0x1d:"h",0x1e:"r",0x20:" ",
 0x21:"G",0x22:"R",0x23:"U",0x24:"I",0x25:"D",0x26:"N",0x27:"E",0x28:"A",
 0x29:"B",0x2a:"F",0x2b:"H",0x2c:"J",0x2d:"M",0x2e:"P",0x2f:"S",
 0x30:"O",0x31:"1",0x32:"2",0x33:"3",0x34:"4",0x35:"5",0x36:"6",0x37:"7",
 0x38:"8",0x39:"9",0x3a:"T",0x3b:"V",0x3c:"(",0x3d:")",0x3e:"L",0x3f:"|"
};
const per = (params && params.width) || 32;
const lines = [];
for (let i = 0; i < bytes.length; i += per) {
  let s = "";
  for (let j = i; j < Math.min(i + per, bytes.length); j++) {
    const b = bytes[j];
    s += (MAP[b] !== undefined) ? MAP[b] : (b === 0x30 ? "0" : "{" + b.toString(16).padStart(2,"0") + "}");
  }
  lines.push(s);
}
return { kind: "text", lines };

const codes = params.codes;
const per = params.per || 20;
const rows = [];
for (let i = 0; i < codes.length; i += per) rows.push(codes.slice(i, i + per));
const W = per * 8, H = rows.length * 9;
const px = new Array(W * H).fill(0);
for (let r = 0; r < rows.length; r++)
  for (let c = 0; c < rows[r].length; c++) {
    const g = rows[r][c] & 0x3f;
    for (let y = 0; y < 8; y++) {
      const b = bytes[g * 8 + y];
      for (let x = 0; x < 8; x++) px[(r * 9 + y) * W + c * 8 + x] = (b >> (7 - x)) & 1;
    }
  }
return { kind: "bitmap", width: W, height: H, pixels: px, palette: ["#000000", "#ffffff"] };

const names = params.names;
const lines = [];
const groups = params.groups;
for (const g of groups) {
  let hdr = "";
  for (const c of g) hdr += (("$" + c.toString(16).padStart(2,"0") + " " + (names[c]||"")).padEnd(16));
  lines.push(hdr);
  for (let y = 0; y < 8; y++) {
    let s = "";
    for (const c of g) {
      const b = bytes[c*8+y];
      let t = "";
      for (let x = 0; x < 8; x++) t += ((b >> (7-x)) & 1) ? "#" : ".";
      lines.push_ = 0;
      s += t + "        ";
    }
    lines.push(s);
  }
  lines.push("");
}
return { kind: "text", lines };

