// Render 8-byte character cells as a picture.
// params.cols  how many glyphs per row (default 8)
// params.codes optional list of glyph numbers to lay out instead of all of them
const cols = params.cols || 8;
const n = Math.floor(bytes.length / 8);
const codes = params.codes || Array.from({length: n}, (_, i) => i);
const rows = [];
for (let i = 0; i < codes.length; i += cols) rows.push(codes.slice(i, i + cols));
const W = cols * 8, H = rows.length * 9;
const px = new Array(W * H).fill(0);
for (let r = 0; r < rows.length; r++)
  for (let c = 0; c < rows[r].length; c++) {
    const g = rows[r][c];
    for (let y = 0; y < 8; y++) {
      const b = bytes[g * 8 + y] || 0;
      for (let x = 0; x < 8; x++) px[(r * 9 + y) * W + c * 8 + x] = (b >> (7 - x)) & 1;
    }
  }
return { kind: "bitmap", width: W, height: H, pixels: px, palette: ["#000000", "#ffffff"] };
